def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for color in counts:
        if color == bg:
            continue
        points = {(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == color}
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in points:
                # Only start at an endpoint of a diagonal run.
                if (r-dr, c-dc) in points:
                    continue
                run = []
                rr, cc = r, c
                while (rr, cc) in points:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                # Extend both ends of each contiguous diagonal line,
                # stopping at any existing non-background cell.
                for sr, sc, step_r, step_c in (
                    (run[0][0]-dr, run[0][1]-dc, -dr, -dc),
                    (run[-1][0]+dr, run[-1][1]+dc, dr, dc),
                ):
                    rr, cc = sr, sc
                    while (0 <= rr < h and 0 <= cc < w
                           and grid[rr][cc] == bg):
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c

    return out
